export const createAndSendBrowseDefinitionGetRequest = (requestService: RequestService,
                                                        responseMsToLive: number,
                                                        href$: string | Observable<string>,
                                                        useCachedVersionIfAvailable: boolean = true): void => {
  if (isNotEmpty(href$)) {
